import bisect

def max_envelopes(envelopes):
    envelopes.sort(key=lambda e: (e[0], -e[1]))
    heights = [h for _, h in envelopes]

    tails = []
    for h in heights:
        idx = bisect.bisect_left(tails, h)
        if idx == len(tails):
            tails.append(h)
        else:
            tails[idx] = h

    return len(tails)

